data=read('/input/data')
nodes=data['nodes']
edges=data['edges']
start=data['start']
ordered=sorted(nodes)
dist={}
for node in nodes:
    dist=putmap(dist,node,-1)
dist=putmap(dist,start,0)
for step in range(len(nodes)):
    changed=False
    for edge in edges:
        u=edge['u']
        v=edge['v']
        w=edge['weight']
        du=get(dist,u,-1)
        dv=get(dist,v,-1)
        if du!=-1 and (dv==-1 or du+w<dv):
            dist=putmap(dist,v,du+w)
            changed=True
    if not changed:
        break
main=[]
for node in ordered:
    main=main+[{'id':node,'distance':get(dist,node,-1)}]
result={'main':main}
